// ValueWith decodes a value of a value alias whose out rows make instances of classes (GN-15c): instance makes the
// instance of the class of a number around its handle, and nil for a number that its package does not make.
func (r *Reader) ValueWith(instance func(class uint64, handle uint64) any) any {
	var made []any
	return r.value(&made, instance)
}

func (r *Reader) value(made *[]any, instance func(class uint64, handle uint64) any) any {
	head := r.take(1)
	if r.failed {
		return nil
	}
	switch head[0] {
	case 0:
		return nil
	case 1:
		return r.Bool()
	case 2:
		return r.Int()
	case 3:
		return r.Float()
	case 4:
		return r.Text()
	case 5:
		return r.Bytes()
	case 6:
		items := make([]any, r.Len())
		*made = append(*made, items)
		for at := range items {
			items[at] = r.value(made, instance)
		}
		return items
	case 7:
		entries := map[string]any{}
		*made = append(*made, entries)
		for at, n := 0, r.Len(); at < n; at++ {
			key, ok := r.value(made, instance).(string)
			if !ok {
				r.fail("U-7: a key of a map[string]any that is not a text")
				return nil
			}
			entries[key] = r.value(made, instance)
		}
		return entries
	case 8:
		index := r.Uint()
		if index >= uint64(len(*made)) {
			r.failed = true
			return nil
		}
		return (*made)[index]
	case 9:
		entries := &KeyedMap[any]{}
		*made = append(*made, entries)
		for at, n := 0, r.Len(); at < n; at++ {
			var key Key
			switch found := r.value(made, instance).(type) {
			case int64:
				key = IntKey(found)
			case string:
				key = TextKey(found)
			case []byte:
				key = BytesKey(found)
			default:
				r.fail("U-7: a key of a keyed map that is no integer, byte string or text")
				return nil
			}
			entries.Set(key, r.value(made, instance))
		}
		return entries
	case 10:
		class, handle := r.Uint(), r.Uint()
		if r.failed {
			return nil
		}
		var made any
		if instance != nil {
			made = instance(class, handle)
		}
		if made == nil {
			r.fail(fmt.Sprintf("U-7: an instance of the class %d that the package of the call does not make", class))
		}
		return made
	case 13:
		index := r.Uint()
		if r.failed || index >= uint64(len(r.funcs)) {
			r.failed = true
			return nil
		}
		return r.funcs[index]
	case 12:
		return r.kept(made, instance)
	case 255:
		r.fail(r.Text())
		return nil
	}
	r.failed = true
	return nil
}

func (r *Reader) fail(problem string) {
	if r.problem == "" {
		r.problem = problem
	}
	r.failed = true
}

// kept makes an instance of a value class without core_type from node 12 of a result (GN-6af): the number of the
// class, then the value that it keeps or the entries of its keyed map.
func (r *Reader) kept(made *[]any, instance func(class uint64, handle uint64) any) any {
	class := r.Uint()
	if r.failed {
		return nil
	}
	switch class {
	case 0:
		entries := &KeyedMap[any]{}
		kept := &StdClass{Properties: entries}
		*made = append(*made, kept)
		for at, n := 0, r.Len(); at < n; at++ {
			var key Key
			switch found := r.value(made, instance).(type) {
			case int64:
				key = IntKey(found)
			case string:
				key = TextKey(found)
			case []byte:
				key = BytesKey(found)
			default:
				r.fail("GN-6af: a key of the entries of StdClass that is no integer, byte string or text")
				return nil
			}
			entries.Set(key, r.value(made, instance))
		}
		return kept
	case 1:
		kept := &Reference{}
		*made = append(*made, kept)
		kept.Value = r.value(made, instance)
		return kept
	}
	r.failed = true
	return nil
}

// StdClass is the value class std_class (GN-6af): it keeps the Go values that NewStdClass judged, and no value of
// the core is behind it. A value that a field is set to is judged where a call reads the instance.
type StdClass struct {
	Properties *KeyedMap[any]
}

// NewStdClass judges its arguments through polyspec_php_serialization::check_std_class (contract member std_class.constructor) and keeps them. A nil
// argument with a default is left out: the instance keeps the default.
func NewStdClass(properties *KeyedMap[any]) (*StdClass, error) {
	call := NewCall()
	defer call.Close()
	enc := NewWriter()
	enc.Uint(uint64(call.handle))
	if properties == nil {
		enc.Tag(false)
	} else {
		enc.Tag(true)
		enc.Len(properties.Len())
		for _, key := range properties.Keys() {
			item, _ := properties.Get(key)
			enc.Key(key)
			call.describe(enc, reflect.ValueOf(item))
		}
	}
	if _, err := invoke(func(pointer *C.uint8_t, length C.size_t, result *C.polyspec_php_serialization__buffer) C.int32_t {
		return C.polyspec_php_serialization__std_class__new(pointer, length, result)
	}, enc.Done()); err != nil {
		return nil, err
	}
	if properties == nil {
		properties = &KeyedMap[any]{}
	}
	return &StdClass{Properties: properties}, nil
}

// Reference is the value class reference (GN-6af): it keeps the Go values that NewReference judged, and no value of
// the core is behind it. A value that a field is set to is judged where a call reads the instance.
type Reference struct {
	Value any
}

// NewReference judges its arguments through polyspec_php_serialization::check_reference (contract member reference.constructor) and keeps them. A nil
// argument with a default is left out: the instance keeps the default.
func NewReference(value_ any) (*Reference, error) {
	call := NewCall()
	defer call.Close()
	enc := NewWriter()
	enc.Uint(uint64(call.handle))
	if value_ == nil {
		enc.Tag(false)
	} else {
		enc.Tag(true)
		call.describe(enc, reflect.ValueOf(value_))
	}
	if _, err := invoke(func(pointer *C.uint8_t, length C.size_t, result *C.polyspec_php_serialization__buffer) C.int32_t {
		return C.polyspec_php_serialization__reference__new(pointer, length, result)
	}, enc.Done()); err != nil {
		return nil, err
	}
	return &Reference{Value: value_}, nil
}

// failure is the data of every error type: the message, the kind, the status and the errno of the core (E-7).
type failure struct {
	message   string
	kind      string
	status    int
	hasStatus bool
	errno     int
	hasErrno  bool
}

// Malformed is the error of a result that does not follow the encoding, which only a fault of the generated code
// makes: kind internal.
func Malformed() error {
	return internalError("the encoded result does not follow the encoding of the binding")
}

func internalError(detail string) error {
	return &PHPSerializationInternalError{failure{message: fmt.Sprintf("internal error: %s", detail), kind: "internal"}}
}

// finished is the error of a failure whose properties were read whole, or kind internal.
func finished(err error, properties *Reader) error {
	if properties.Finish() != nil {
		return Malformed()
	}
	return err
}

// decodeFailure reads an encoded failure: the category, the message, the kind, the status, the errno, the class of
// the kind with the properties of its unit (E-2, I-3), and the error that a Go callback returned (U-3), which the call
// returns unchanged.
func decodeFailure(r *Reader) error {
	head := r.take(1)
	f := failure{message: r.Text(), kind: r.Text()}
	if r.Tag() {
		f.status, f.hasStatus = int(r.Uint()), true
	}
	if r.Tag() {
		f.errno, f.hasErrno = int(r.Int()), true
	}
	class := r.take(1)
	properties := NewReader(r.Bytes())
	properties.funcs = r.funcs
	var call, index uint64
	present := r.Tag()
	if present {
		call, index = r.Uint(), r.Uint()
	}
	if r.Finish() != nil {
		return Malformed()
	}
	if present {
		return raisedError(call, index)
	}
	category := head[0]
	switch class[0] {
	case 0:
		switch category {
		case 0:
			return finished(&PHPSerializationValueError{f}, properties)
		case 1:
			return finished(&PHPSerializationTypeError{f}, properties)
		case 2:
			return finished(&PHPSerializationIoError{f}, properties)
		case 3:
			return finished(&PHPSerializationStoreError{f}, properties)
		case 4:
			return finished(&PHPSerializationBusyError{f}, properties)
		case 5:
			return finished(&PHPSerializationInternalError{f}, properties)
		}
	case 1:
		if category != 0 {
			return Malformed()
		}
		return finished(makeFormatError(&PHPSerializationValueError{f}, properties), properties)
	}
	return Malformed()
}

// PHPSerializationValueError is an error of category value (E-7).
type PHPSerializationValueError struct{ failure }

// Error is the message of the failure (B-1).
func (e *PHPSerializationValueError) Error() string { return e.message }

// Kind is the kind of the failure (B-4).
func (e *PHPSerializationValueError) Kind() string { return e.kind }

// Status is the HTTP status of the kind, when it has one (B-4).
func (e *PHPSerializationValueError) Status() (int, bool) { return e.status, e.hasStatus }

// Errno is the OS error number of an I/O failure, when there is one (B-4).
func (e *PHPSerializationValueError) Errno() (int, bool) { return e.errno, e.hasErrno }

