// FormatError is the error unit format_error (E-2): an error of category value,
// which errors.As finds as each of them too.
type FormatError struct {
	*PHPSerializationValueError
	pOffset *uint64
}

// Unwrap is the error of the category, which errors.As reads on.
func (e *FormatError) Unwrap() error { return e.PHPSerializationValueError }

// Offset is the property format_error.offset (I-3).
func (e *FormatError) Offset() *uint64 { return e.pOffset }

func makeFormatError(base *PHPSerializationValueError, r *Reader) *FormatError {
	e := &FormatError{PHPSerializationValueError: base}
	if r.Tag() {
		var present0 uint64
		present0 = r.Uint()
		e.pOffset = &present0
	}
	return e
}

// The static library calls these exports through C (B-8). The initializer takes the value of each, so a call graph
// of the Go code alone, such as that of deadcode, reaches them and what they call (GN-15h).
var _ = [...]any{
	polyspec_php_serialization___go_host,
	polyspec_php_serialization___go_release,
	polyspec_php_serialization___go_native,
}
